fn move_visible_primary_cursor_up(runtime_shell: &mut BevyRuntimeShell) -> Result<()> {
    move_visible_primary_cursor(runtime_shell, -1)
}

fn move_visible_primary_cursor_down(runtime_shell: &mut BevyRuntimeShell) -> Result<()> {
    move_visible_primary_cursor(runtime_shell, 1)
}

fn move_visible_primary_cursor_left(runtime_shell: &mut BevyRuntimeShell) -> Result<()> {
    if runtime_shell.title_menu.is_some() {
        return move_visible_title_menu_cursor(runtime_shell, -1);
    }
    let snapshot = runtime_shell.shell.snapshot()?;
    if snapshot.battle.is_some() {
        if runtime_shell.battle_pack_target_mode.is_some() {
            return move_visible_battle_pack_target_secondary_cursor(runtime_shell, -1);
        }
        if runtime_shell.ball_cursor.is_some() || runtime_shell.bag_cursor.is_some() {
            return move_visible_battle_item_list_cursor(runtime_shell, -1);
        }
        if runtime_shell.battle_switch_cursor.is_some() {
            return move_visible_battle_switch_cursor(runtime_shell, -1);
        }
        if runtime_shell.battle_move_cursor.is_some() {
            return move_visible_battle_move_cursor(runtime_shell, -1);
        }
        return move_visible_battle_action_cursor(runtime_shell, -1);
    }
    if snapshot.pending_shop.is_some() {
        return toggle_visible_shop_sell_mode(runtime_shell);
    }
    if visible_field_pack_is_open(runtime_shell) {
        if runtime_shell.field_pack_target_mode.is_some() {
            return move_visible_field_pack_target_secondary_cursor(runtime_shell, -1);
        }
        return shift_visible_field_pack_pocket(runtime_shell, -1);
    }
    if runtime_shell.storage_cursor.is_some() {
        return switch_visible_pc_box_by_delta(runtime_shell, -1);
    }
    if runtime_shell.options_menu_open {
        return change_visible_options_selection(runtime_shell, -1);
    }
    if runtime_shell.pc_item_cursor.is_some() {
        return move_visible_pc_item_cursor(runtime_shell, -1);
    }
    move_visible_primary_cursor(runtime_shell, -1)
}

fn move_visible_primary_cursor_right(runtime_shell: &mut BevyRuntimeShell) -> Result<()> {
    if runtime_shell.title_menu.is_some() {
        return move_visible_title_menu_cursor(runtime_shell, 1);
    }
    let snapshot = runtime_shell.shell.snapshot()?;
    if snapshot.battle.is_some() {
        if runtime_shell.battle_pack_target_mode.is_some() {
            return move_visible_battle_pack_target_secondary_cursor(runtime_shell, 1);
        }
        if runtime_shell.ball_cursor.is_some() || runtime_shell.bag_cursor.is_some() {
            return move_visible_battle_item_list_cursor(runtime_shell, 1);
        }
        if runtime_shell.battle_switch_cursor.is_some() {
            return move_visible_battle_switch_cursor(runtime_shell, 1);
        }
        if runtime_shell.battle_move_cursor.is_some() {
            return move_visible_battle_move_cursor(runtime_shell, 1);
        }
        return move_visible_battle_action_cursor(runtime_shell, 1);
    }
    if snapshot.pending_shop.is_some() {
        return toggle_visible_shop_sell_mode(runtime_shell);
    }
    if visible_field_pack_is_open(runtime_shell) {
        if runtime_shell.field_pack_target_mode.is_some() {
            return move_visible_field_pack_target_secondary_cursor(runtime_shell, 1);
        }
        return shift_visible_field_pack_pocket(runtime_shell, 1);
    }
    if runtime_shell.storage_cursor.is_some() {
        return switch_visible_pc_box_by_delta(runtime_shell, 1);
    }
    if runtime_shell.options_menu_open {
        return change_visible_options_selection(runtime_shell, 1);
    }
    if runtime_shell.pc_item_cursor.is_some() {
        return move_visible_pc_item_cursor(runtime_shell, 1);
    }
    move_visible_primary_cursor(runtime_shell, 1)
}

fn move_visible_battle_item_list_cursor(
    runtime_shell: &mut BevyRuntimeShell,
    delta: isize,
) -> Result<()> {
    if runtime_shell.ball_cursor.is_some() {
        return move_visible_ball_cursor(runtime_shell, delta);
    }
    if runtime_shell.bag_cursor.is_some() {
        return move_visible_battle_bag_cursor(runtime_shell, delta);
    }
    record_visible_runtime_action(runtime_shell, "battle:item_list:move:none")?;
    runtime_shell
        .last_audio_events
        .push("no open battle item list".to_string());
    set_shell_action_status(runtime_shell, "NO BATTLE ITEMS");
    trim_event_log(&mut runtime_shell.last_audio_events);
    Ok(())
}

fn move_visible_primary_cursor(runtime_shell: &mut BevyRuntimeShell, delta: isize) -> Result<()> {
    if runtime_shell.title_menu.is_some() {
        return move_visible_title_menu_cursor(runtime_shell, delta);
    }
    let snapshot = runtime_shell.shell.snapshot()?;
    if runtime_shell.start_menu_cursor.is_some() {
        return move_visible_start_menu_cursor(runtime_shell, delta);
    }
    if runtime_shell.pending_phone_prompt.is_some() {
        return move_visible_phone_prompt_cursor(runtime_shell, delta);
    }
    if snapshot.ui.pending_yes_no.is_some() {
        return move_visible_yes_no_cursor(runtime_shell, delta);
    }
    if snapshot.pending_move_learn.is_some() {
        return move_visible_pending_move_learn_cursor(runtime_shell, delta);
    }
    if runtime_shell.party_menu_open {
        if runtime_shell.party_summary_open {
            return move_visible_party_cursor(runtime_shell, delta);
        }
        if runtime_shell.fly_cursor.is_some() {
            return move_visible_fly_cursor(runtime_shell, delta);
        }
        if runtime_shell.party_switch_cursor.is_some() {
            return move_visible_party_switch_cursor(runtime_shell, delta);
        }
        if runtime_shell.party_action_cursor.is_some() {
            return move_visible_party_action_cursor(runtime_shell, delta);
        }
        return move_visible_party_cursor(runtime_shell, delta);
    }
    if runtime_shell.storage_cursor.is_some() {
        return move_visible_storage_cursor(runtime_shell, delta);
    }
    if runtime_shell.pc_item_cursor.is_some() {
        return move_visible_pc_item_cursor(runtime_shell, delta);
    }
    if runtime_shell.pokedex_menu_open {
        return move_visible_pokedex_cursor(runtime_shell, delta);
    }
    if runtime_shell.pokegear_menu_open {
        return move_visible_pokegear_cursor(runtime_shell, delta);
    }
    if runtime_shell.options_menu_open {
        return move_visible_options_cursor(runtime_shell, delta);
    }
    if visible_field_pack_is_open(runtime_shell) {
        if runtime_shell.field_pack_target_mode.is_some() {
            return move_visible_field_pack_target_cursor(runtime_shell, delta);
        }
        return move_visible_active_field_pack_cursor(runtime_shell, delta);
    }
    if let Some(battle) = &snapshot.battle {
        if battle.commands.can_use_items {
            if runtime_shell.ball_cursor.is_some() {
                return move_visible_ball_cursor(runtime_shell, delta);
            }
            if runtime_shell.bag_cursor.is_some() {
                if runtime_shell.battle_pack_target_mode.is_some() {
                    return move_visible_battle_pack_target_cursor(runtime_shell, delta);
                }
                return move_visible_battle_bag_cursor(runtime_shell, delta);
            }
        }
        if runtime_shell.battle_move_cursor.is_some() {
            return move_visible_battle_move_cursor(runtime_shell, delta);
        }
        if runtime_shell.battle_switch_cursor.is_some() {
            return move_visible_battle_switch_cursor(runtime_shell, delta);
        }
        return move_visible_battle_action_cursor(runtime_shell, delta);
    }
    if has_visible_elevator_prompt(&snapshot, runtime_shell) {
        return move_visible_elevator_cursor(runtime_shell, delta);
    }
    if has_visible_gift_pokemon_prompt(&snapshot, runtime_shell) {
        return move_visible_gift_pokemon_cursor(runtime_shell, delta);
    }
    if snapshot.pending_shop.is_some() {
        if runtime_shell.sell_cursor.is_some() {
            return move_visible_sell_cursor(runtime_shell, delta);
        }
        return move_visible_shop_buy_cursor(runtime_shell, delta);
    }
    if snapshot.ui.menu.is_some() {
        return move_visible_menu_cursor(runtime_shell, delta);
    }
    if let Some(option_count) = visible_script_surface_option_count(&snapshot, runtime_shell) {
        shift_visible_script_command_cursor_bounded(runtime_shell, delta, option_count);
    }
    Ok(())
}

fn visible_title_menu_options(
    runtime_shell: &BevyRuntimeShell,
    title: &TitleMenu,
) -> Vec<TitleMenuOption> {
    let mut options = Vec::new();
    if title_continue_save_path(runtime_shell, title).is_some() {
        options.push(TitleMenuOption::Continue);
    }
    options.push(TitleMenuOption::NewGame);
    options
}

fn title_continue_save_path<'a>(
    _runtime_shell: &BevyRuntimeShell,
    title: &'a TitleMenu,
) -> Option<&'a PathBuf> {
    let path = title.save_path.as_ref()?;
    if path.exists() {
        return Some(path);
    }
    None
}

fn visible_title_continue_entries(
    runtime_shell: &BevyRuntimeShell,
    title: &TitleMenu,
) -> Vec<String> {
    let Some(path) = title_continue_save_path(runtime_shell, title) else {
        return vec!["CONTINUE NONE".to_string()];
    };
    let mut entries = vec![compact_scene_label(
        &format!(
            "CONTINUE {}",
            path.file_name()
                .map(|name| name.to_string_lossy().to_string())
                .unwrap_or_else(|| path.to_string_lossy().to_string())
        ),
        30,
    )];
    match runtime_shell.shell.runtime().load_save_summary(path) {
        Ok(_) => entries.extend(visible_save_slot_preview_entries_for_path(
            runtime_shell,
            path,
        )),
        Err(error) => entries.push(compact_scene_label(&format!("INVALID SAVE {error}"), 30)),
    }
    entries.into_iter().take(4).collect()
}

fn visible_title_menu_entries(
    runtime_shell: &BevyRuntimeShell,
    title: &TitleMenu,
) -> Result<Vec<String>> {
    let options = visible_title_menu_options(runtime_shell, title);
    let selected = title.cursor.option_index.min(options.len() - 1);
    Ok(options
        .iter()
        .enumerate()
        .map(|(index, option)| {
            let marker = if index == selected { ">" } else { " " };
            let label = match option {
                TitleMenuOption::Continue => "CONTINUE",
                TitleMenuOption::NewGame => "NEW GAME",
            };
            format!("{marker}{label}")
        })
        .collect())
}

fn move_visible_title_menu_cursor(
    runtime_shell: &mut BevyRuntimeShell,
    delta: isize,
) -> Result<()> {
    let action = format!("title:cursor:{delta}");
    move_visible_title_menu_cursor_with_action(runtime_shell, delta, action)
}

fn move_visible_title_menu_cursor_with_action(
    runtime_shell: &mut BevyRuntimeShell,
    delta: isize,
    action: String,
) -> Result<()> {
    let Some(title) = runtime_shell.title_menu.as_ref() else {
        return handle_visible_no_active_title_menu(runtime_shell, "cursor");
    };
    let len = visible_title_menu_options(runtime_shell, title).len();
    let current = title.cursor.option_index.min(len - 1);
    let next = if delta.is_negative() {
        current.checked_sub(delta.unsigned_abs()).unwrap_or(len - 1)
    } else {
        (current + delta as usize) % len
    };
    if let Some(title) = runtime_shell.title_menu.as_mut() {
        title.cursor.option_index = next;
    }
    record_visible_runtime_action(runtime_shell, format!("{action}:{current}->{next}"))?;
    runtime_shell
        .last_audio_events
        .push(format!("title cursor {}->{}", current + 1, next + 1));
    set_shell_action_status(runtime_shell, format!("TITLE OPTION {}", next + 1));
    trim_event_log(&mut runtime_shell.last_audio_events);
    Ok(())
}

fn press_visible_title_direction_button(
    runtime_shell: &mut BevyRuntimeShell,
    input: GameButton,
    delta: isize,
) -> Result<()> {
    let action = format!("input:title:{input:?}:{delta}");
    move_visible_title_menu_cursor_with_action(runtime_shell, delta, action)
}

fn selected_visible_title_menu_option(
    runtime_shell: &BevyRuntimeShell,
    title: &TitleMenu,
) -> Result<TitleMenuOption> {
    let options = visible_title_menu_options(runtime_shell, title);
    let selected = title.cursor.option_index.min(options.len() - 1);
    Ok(options[selected])
}

fn press_visible_title_confirm_button(
    runtime_shell: &mut BevyRuntimeShell,
    input: GameButton,
) -> Result<()> {
    let action = format!("input:title:{input:?}:confirm");
    record_visible_runtime_action(runtime_shell, action.clone())?;
    runtime_shell.last_audio_events.push(action);
    trim_event_log(&mut runtime_shell.last_audio_events);
    select_visible_title_menu_option(runtime_shell)
}

fn press_visible_title_cancel_button(runtime_shell: &mut BevyRuntimeShell) -> Result<()> {
    record_visible_runtime_action(runtime_shell, "input:title:B:cancel")?;
    runtime_shell
        .last_audio_events
        .push("input:title:B:cancel".to_string());
    set_shell_action_status(runtime_shell, "TITLE");
    trim_event_log(&mut runtime_shell.last_audio_events);
    Ok(())
}

fn select_visible_title_menu_option(runtime_shell: &mut BevyRuntimeShell) -> Result<()> {
    let Some(title) = runtime_shell.title_menu.clone() else {
        return handle_visible_no_active_title_menu(runtime_shell, "confirm");
    };
    let mut arm_new_game_arrival = false;
    match selected_visible_title_menu_option(runtime_shell, &title)? {
        TitleMenuOption::Continue => {
            let save_path = title
                .save_path
                .context("title Continue requires an exact save path")?;
            let summary = match runtime_shell.shell.runtime().load_save_summary(&save_path) {
                Ok(summary) => summary,
                Err(error) => {
                    record_visible_runtime_action(
                        runtime_shell,
                        format!("title:continue:invalid:{}:{error}", save_path.display()),
                    )?;
                    set_shell_action_status(
                        runtime_shell,
                        compact_scene_label(&format!("INVALID SAVE {error}"), 30),
                    );
                    return Err(error).with_context(|| {
                        format!("title Continue rejected {}", save_path.display())
                    });
                }
            };
            record_visible_runtime_action(
                runtime_shell,
                format!(
                    "title:continue:{}:{}:{}:{}",
                    save_path.display(),
                    summary.modpack().id(),
                    summary.modpack().hash(),
                    summary.pack_content_hash()
                ),
            )?;
            runtime_shell.title_menu = None;
            runtime_shell.last_audio_events.push(format!(
                "title continue loaded {}",
                save_path.to_string_lossy()
            ));
            set_shell_action_status(
                runtime_shell,
                format!("CONTINUE {}", save_path.to_string_lossy()),
            );
            load_visible_runtime_save(runtime_shell, &save_path, "title_continue")?;
        }
        TitleMenuOption::NewGame => {
            runtime_shell.shell = RuntimeGameShell::new_game(
                runtime_shell.asset_root.clone(),
                runtime_shell.runtime.clone(),
                title.spawn_identifier,
            )?;
            runtime_shell.title_menu = None;
            reset_visible_navigation_state(runtime_shell);
            reset_visible_deterministic_session_history(runtime_shell)?;
            let snapshot = runtime_shell.shell.snapshot()?;
            let modpack_id = snapshot.boot.modpack_id.clone();
            let modpack_hash = runtime_shell.shell.runtime().modpack().hash().to_string();
            let pack_content_hash = snapshot.boot.pack_content_hash.clone();
            record_visible_runtime_action(
                runtime_shell,
                format!(
                    "title:new_game:{}:{}:{}:{}",
                    title.spawn_identifier, modpack_id, modpack_hash, pack_content_hash
                ),
            )?;
            reset_visible_music_state(runtime_shell);
            runtime_shell
                .last_audio_events
                .push(format!("title new game spawn={}", title.spawn_identifier));
            set_shell_action_status(
                runtime_shell,
                format!("NEW GAME SPAWN {}", title.spawn_identifier),
            );
            open_visible_player_name_input(runtime_shell)?;
            arm_new_game_arrival = runtime_shell.pending_name_input.is_none();
        }
    }
    if arm_new_game_arrival {
        settle_visible_overworld_arrival(runtime_shell, "new_game")?;
    }
    trim_event_log(&mut runtime_shell.last_audio_events);
    Ok(())
}

fn open_visible_player_name_input(runtime_shell: &mut BevyRuntimeShell) -> Result<()> {
    let snapshot = runtime_shell.shell.snapshot()?;
    if !snapshot.trainer.player_name.is_empty() {
        return Ok(());
    }
    runtime_shell.pending_name_input = Some(PendingNameInput {
        label: "PLAYER NAME".to_string(),
        value: String::new(),
        cursor_index: 0,
    });
    runtime_shell
        .last_audio_events
        .push("opened player name input".to_string());
    set_shell_action_status(runtime_shell, "PLAYER NAME");
    Ok(())
}

fn apply_visible_name_input_keys(
    keys: &ButtonInput<KeyCode>,
    runtime_shell: &mut BevyRuntimeShell,
) {
    let shift_pressed = keys.pressed(KeyCode::ShiftLeft) || keys.pressed(KeyCode::ShiftRight);
    let alt_pressed = keys.pressed(KeyCode::AltLeft) || keys.pressed(KeyCode::AltRight);
    let ctrl_pressed = keys.pressed(KeyCode::ControlLeft) || keys.pressed(KeyCode::ControlRight);
    if alt_pressed || ctrl_pressed {
        return;
    }
    if keys.just_pressed(KeyCode::ArrowLeft) {
        run_bevy_action(runtime_shell, move_visible_player_name_cursor_left);
        return;
    }
    if keys.just_pressed(KeyCode::ArrowRight) {
        run_bevy_action(runtime_shell, move_visible_player_name_cursor_right);
        return;
    }
    if keys.just_pressed(KeyCode::ArrowUp) {
        run_bevy_action(runtime_shell, move_visible_player_name_cursor_up);
        return;
    }
    if keys.just_pressed(KeyCode::ArrowDown) {
        run_bevy_action(runtime_shell, move_visible_player_name_cursor_down);
        return;
    }
    if keys.just_pressed(KeyCode::KeyZ) && !shift_pressed {
        run_bevy_action(runtime_shell, select_visible_player_name_grid_key);
        return;
    }
    if keys.just_pressed(KeyCode::KeyX) && !shift_pressed {
        run_bevy_action(runtime_shell, delete_visible_player_name_char);
        return;
    }
    if keys.just_pressed(KeyCode::Enter) {
        run_bevy_action(runtime_shell, confirm_visible_player_name_input);
        return;
    }
    if keys.just_pressed(KeyCode::Escape) {
        run_bevy_action(runtime_shell, clear_visible_player_name_input);
        return;
    }
    if keys.just_pressed(KeyCode::Backspace) {
        run_bevy_action(runtime_shell, delete_visible_player_name_char);
        return;
    }
    if keys.just_pressed(KeyCode::Space) {
        run_bevy_action(runtime_shell, append_visible_player_name_space);
        return;
    }
    if let Some(ch) = visible_name_input_key_char(keys, shift_pressed) {
        if let Some(action) = visible_name_input_append_action(ch) {
            run_bevy_action(runtime_shell, action);
        }
    }
}

