fn visible_name_input_grid_width() -> usize {
    9
}

fn visible_name_input_key_label(key: NameInputKey) -> String {
    match key {
        NameInputKey::Char(ch) => ch.to_string(),
        NameInputKey::Space => "SP".to_string(),
        NameInputKey::Delete => "DEL".to_string(),
        NameInputKey::End => "END".to_string(),
    }
}

fn move_visible_player_name_cursor_left(runtime_shell: &mut BevyRuntimeShell) -> Result<()> {
    move_visible_player_name_cursor(runtime_shell, -1, 0)
}

fn move_visible_player_name_cursor_right(runtime_shell: &mut BevyRuntimeShell) -> Result<()> {
    move_visible_player_name_cursor(runtime_shell, 1, 0)
}

fn move_visible_player_name_cursor_up(runtime_shell: &mut BevyRuntimeShell) -> Result<()> {
    move_visible_player_name_cursor(runtime_shell, 0, -1)
}

fn move_visible_player_name_cursor_down(runtime_shell: &mut BevyRuntimeShell) -> Result<()> {
    move_visible_player_name_cursor(runtime_shell, 0, 1)
}

fn move_visible_player_name_cursor(
    runtime_shell: &mut BevyRuntimeShell,
    dx: isize,
    dy: isize,
) -> Result<()> {
    let Some(input) = runtime_shell.pending_name_input.as_ref() else {
        return handle_visible_no_player_name_input(runtime_shell, "cursor");
    };
    let len = visible_name_input_keys().len();
    let width = visible_name_input_grid_width();
    let height = (len + width - 1) / width;
    let row = input.cursor_index / width;
    let col = input.cursor_index % width;
    let next_row = (row as isize + dy).rem_euclid(height as isize) as usize;
    let next_col = (col as isize + dx).rem_euclid(width as isize) as usize;
    let next_index = (next_row * width + next_col).min(len.saturating_sub(1));
    record_visible_runtime_action(runtime_shell, format!("player_name:cursor:{next_index}"))?;
    let input = runtime_shell
        .pending_name_input
        .as_mut()
        .context("no player name input is open")?;
    input.cursor_index = next_index;
    runtime_shell
        .last_audio_events
        .push(format!("player name cursor {next_index}"));
    trim_event_log(&mut runtime_shell.last_audio_events);
    Ok(())
}

fn select_visible_player_name_grid_key(runtime_shell: &mut BevyRuntimeShell) -> Result<()> {
    let cursor_index = runtime_shell
        .pending_name_input
        .as_ref()
        .map(|input| input.cursor_index)
        .context("no player name input is open")?;
    let key = *visible_name_input_keys()
        .get(cursor_index)
        .context("player name cursor is outside the name input grid")?;
    record_visible_runtime_action(
        runtime_shell,
        format!(
            "player_name:grid:{}:{}",
            cursor_index,
            visible_name_input_key_label(key)
        ),
    )?;
    match key {
        NameInputKey::Char(ch) => append_visible_player_name_char(runtime_shell, ch),
        NameInputKey::Space => append_visible_player_name_char(runtime_shell, ' '),
        NameInputKey::Delete => delete_visible_player_name_char(runtime_shell),
        NameInputKey::End => confirm_visible_player_name_input(runtime_shell),
    }
}

fn visible_name_input_key_char(keys: &ButtonInput<KeyCode>, lowercase: bool) -> Option<char> {
    let letter = [
        (KeyCode::KeyA, 'A'),
        (KeyCode::KeyB, 'B'),
        (KeyCode::KeyC, 'C'),
        (KeyCode::KeyD, 'D'),
        (KeyCode::KeyE, 'E'),
        (KeyCode::KeyF, 'F'),
        (KeyCode::KeyG, 'G'),
        (KeyCode::KeyH, 'H'),
        (KeyCode::KeyI, 'I'),
        (KeyCode::KeyJ, 'J'),
        (KeyCode::KeyK, 'K'),
        (KeyCode::KeyL, 'L'),
        (KeyCode::KeyM, 'M'),
        (KeyCode::KeyN, 'N'),
        (KeyCode::KeyO, 'O'),
        (KeyCode::KeyP, 'P'),
        (KeyCode::KeyQ, 'Q'),
        (KeyCode::KeyR, 'R'),
        (KeyCode::KeyS, 'S'),
        (KeyCode::KeyT, 'T'),
        (KeyCode::KeyU, 'U'),
        (KeyCode::KeyV, 'V'),
        (KeyCode::KeyW, 'W'),
        (KeyCode::KeyX, 'X'),
        (KeyCode::KeyY, 'Y'),
        (KeyCode::KeyZ, 'Z'),
    ]
    .into_iter()
    .find_map(|(key, ch)| {
        keys.just_pressed(key).then_some(if lowercase {
            ch.to_ascii_lowercase()
        } else {
            ch
        })
    });
    if letter.is_some() {
        return letter;
    }
    [
        (KeyCode::Digit0, '0'),
        (KeyCode::Digit1, '1'),
        (KeyCode::Digit2, '2'),
        (KeyCode::Digit3, '3'),
        (KeyCode::Digit4, '4'),
        (KeyCode::Digit5, '5'),
        (KeyCode::Digit6, '6'),
        (KeyCode::Digit7, '7'),
        (KeyCode::Digit8, '8'),
        (KeyCode::Digit9, '9'),
    ]
    .into_iter()
    .find_map(|(key, ch)| keys.just_pressed(key).then_some(ch))
}

