fn append_visible_player_name_char(runtime_shell: &mut BevyRuntimeShell, ch: char) -> Result<()> {
    let Some(input) = runtime_shell.pending_name_input.as_ref() else {
        return handle_visible_no_player_name_input(runtime_shell, "append");
    };
    if input.value.len() >= PLAYER_NAME_LENGTH {
        record_visible_runtime_action(runtime_shell, format!("player_name:full:{ch}"))?;
        runtime_shell
            .last_audio_events
            .push("player name full".to_string());
        trim_event_log(&mut runtime_shell.last_audio_events);
        return Ok(());
    }
    record_visible_runtime_action(runtime_shell, format!("player_name:append:{ch}"))?;
    let input = runtime_shell
        .pending_name_input
        .as_mut()
        .context("no player name input is open")?;
    input.value.push(ch);
    runtime_shell
        .last_audio_events
        .push(format!("player name add {ch}"));
    trim_event_log(&mut runtime_shell.last_audio_events);
    Ok(())
}

fn delete_visible_player_name_char(runtime_shell: &mut BevyRuntimeShell) -> Result<()> {
    if runtime_shell.pending_name_input.is_none() {
        return handle_visible_no_player_name_input(runtime_shell, "delete");
    }
    record_visible_runtime_action(runtime_shell, "player_name:delete")?;
    let input = runtime_shell
        .pending_name_input
        .as_mut()
        .context("no player name input is open")?;
    input.value.pop();
    runtime_shell
        .last_audio_events
        .push("player name delete".to_string());
    trim_event_log(&mut runtime_shell.last_audio_events);
    Ok(())
}

fn clear_visible_player_name_input(runtime_shell: &mut BevyRuntimeShell) -> Result<()> {
    if runtime_shell.pending_name_input.is_none() {
        return handle_visible_no_player_name_input(runtime_shell, "clear");
    }
    record_visible_runtime_action(runtime_shell, "player_name:clear")?;
    let input = runtime_shell
        .pending_name_input
        .as_mut()
        .context("no player name input is open")?;
    input.value.clear();
    runtime_shell
        .last_audio_events
        .push("player name cleared".to_string());
    trim_event_log(&mut runtime_shell.last_audio_events);
    Ok(())
}

fn set_visible_player_name_input_value(
    runtime_shell: &mut BevyRuntimeShell,
    value: &str,
) -> Result<()> {
    runtime_shell
        .pending_name_input
        .as_ref()
        .context("no player name input is open")?;
    if value.len() > PLAYER_NAME_LENGTH {
        anyhow::bail!(
            "player name length {} exceeds Crystal limit {}",
            value.len(),
            PLAYER_NAME_LENGTH
        );
    }
    if value.trim() != value || value.is_empty() || value.chars().any(char::is_control) {
        anyhow::bail!("player name must be non-empty, exact, and contain no control characters");
    }
    record_visible_runtime_action(runtime_shell, format!("player_name:set:{value}"))?;
    let input = runtime_shell
        .pending_name_input
        .as_mut()
        .context("no player name input is open")?;
    input.value.clear();
    input.value.push_str(value);
    runtime_shell
        .last_audio_events
        .push(format!("player name set {value}"));
    trim_event_log(&mut runtime_shell.last_audio_events);
    Ok(())
}

fn complete_visible_smoke_player_name_if_needed(
    runtime_shell: &mut BevyRuntimeShell,
) -> Result<()> {
    if runtime_shell.pending_name_input.is_none() {
        return Ok(());
    }
    set_visible_player_name_input_value(runtime_shell, "CHRIS")?;
    confirm_visible_player_name_input(runtime_shell)
}

fn confirm_visible_player_name_input(runtime_shell: &mut BevyRuntimeShell) -> Result<()> {
    let Some(input) = runtime_shell.pending_name_input.take() else {
        return handle_visible_no_player_name_input(runtime_shell, "confirm");
    };
    if input.value.trim() != input.value || input.value.is_empty() {
        runtime_shell.pending_name_input = Some(input);
        anyhow::bail!("player name must be non-empty and exact");
    }
    let snapshot = runtime_shell.shell.snapshot()?;
    record_visible_runtime_action(
        runtime_shell,
        format!(
            "trainer:identity:{}:{}",
            input.value, snapshot.trainer.player_id
        ),
    )?;
    let identity = runtime_shell
        .shell
        .set_trainer_identity(input.value, snapshot.trainer.player_id)?;
    let identity_checksum = identity.state_checksum.clone();
    runtime_shell.deterministic_session_start = identity_checksum.clone();
    runtime_shell.deterministic_session_checkpoint =
        visible_deterministic_session_checkpoint(&runtime_shell.shell, identity_checksum)
            .context("refresh deterministic session checkpoint after trainer identity")?;
    runtime_shell.last_audio_events.push(format!(
        "trainer identity name={} id={} checksum={:?}",
        identity.player_name_after, identity.player_id_after, identity.state_checksum
    ));
    set_shell_action_status(runtime_shell, "PLAYER READY");
    settle_visible_overworld_arrival(runtime_shell, "new_game")?;
    Ok(())
}

fn reset_visible_music_state(runtime_shell: &mut BevyRuntimeShell) {
    runtime_shell.active_music = None;
    runtime_shell.faded_music = None;
    runtime_shell.pending_music_stop = true;
    clear_pending_music_commands(&mut runtime_shell.pending_audio);
}

fn visible_script_surface_option_count(
    snapshot: &RuntimeShellSnapshot,
    runtime_shell: &BevyRuntimeShell,
) -> Option<usize> {
    if has_visible_elevator_prompt(snapshot, runtime_shell) {
        return Some(visible_elevator_option_count(snapshot, runtime_shell).max(1));
    }
    let gift_count = visible_gift_pokemon_prompt_options(snapshot, runtime_shell).len();
    if gift_count > 0 {
        return Some(gift_count);
    }
    None
}

fn elevator_surface_id(source_script: &str, command_index: usize) -> String {
    format!("ui:elevators:{source_script}:{command_index}")
}

fn visible_elevator_prompt_options<'a>(
    snapshot: &'a RuntimeShellSnapshot,
    runtime_shell: &BevyRuntimeShell,
) -> Vec<&'a RuntimeElevatorSnapshot> {
    let Some(cursor) = runtime_shell.elevator_cursor.as_ref() else {
        return Vec::new();
    };
    snapshot
        .ui
        .elevators
        .iter()
        .filter(|elevator| {
            elevator.map_name == snapshot.overworld.map_name
                && elevator_surface_id(&elevator.source_script, elevator.elevator_command_index)
                    == cursor.surface_id
        })
        .collect()
}

fn has_visible_elevator_prompt(
    snapshot: &RuntimeShellSnapshot,
    runtime_shell: &BevyRuntimeShell,
) -> bool {
    !visible_elevator_prompt_options(snapshot, runtime_shell).is_empty()
}

fn visible_elevator_option_count(
    snapshot: &RuntimeShellSnapshot,
    runtime_shell: &BevyRuntimeShell,
) -> usize {
    visible_elevator_prompt_options(snapshot, runtime_shell)
        .iter()
        .map(|elevator| elevator.floors.len())
        .sum()
}

fn gift_pokemon_surface_id(source_script: &str, command_index: usize) -> String {
    format!("ui:gift-pokemon:{source_script}:{command_index}")
}

fn visible_gift_pokemon_prompt_options<'a>(
    snapshot: &'a RuntimeShellSnapshot,
    runtime_shell: &BevyRuntimeShell,
) -> Vec<&'a RuntimeGiftPokemonSnapshot> {
    let Some(cursor) = runtime_shell.gift_pokemon_cursor.as_ref() else {
        return Vec::new();
    };
    snapshot
        .ui
        .gift_pokemon
        .iter()
        .filter(|gift| {
            gift.map_name == snapshot.overworld.map_name
                && gift_pokemon_surface_id(&gift.source_script, gift.command_index)
                    == cursor.surface_id
        })
        .collect()
}

fn has_visible_gift_pokemon_prompt(
    snapshot: &RuntimeShellSnapshot,
    runtime_shell: &BevyRuntimeShell,
) -> bool {
    !visible_gift_pokemon_prompt_options(snapshot, runtime_shell).is_empty()
}

fn selected_visible_elevator_option(
    runtime_shell: &mut BevyRuntimeShell,
    snapshot: &RuntimeShellSnapshot,
) -> Result<(usize, usize)> {
    let elevators = visible_elevator_prompt_options(snapshot, runtime_shell);
    let option_count = visible_elevator_option_count(snapshot, runtime_shell);
    if option_count == 0 {
        anyhow::bail!("compiled visible elevators have no floors");
    }
    let surface_id = runtime_shell
        .elevator_cursor
        .as_ref()
        .map(|cursor| cursor.surface_id.clone())
        .context("elevator prompt requires a cursor surface")?;
    let selected =
        strict_readonly_cursor_index(&runtime_shell.elevator_cursor, &surface_id, option_count)
            .context("elevator prompt is active without a valid cursor")?;
    let mut offset = 0usize;
    for (elevator_index, elevator) in elevators.iter().enumerate() {
        let next_offset = offset + elevator.floors.len();
        if selected < next_offset {
            return Ok((elevator_index, selected - offset));
        }
        offset = next_offset;
    }
    anyhow::bail!("selected elevator option {selected} is outside visible elevators")
}

fn move_visible_elevator_cursor(runtime_shell: &mut BevyRuntimeShell, delta: isize) -> Result<()> {
    let snapshot = runtime_shell.shell.snapshot()?;
    let option_count = visible_elevator_option_count(&snapshot, runtime_shell);
    if option_count == 0 {
        return handle_visible_no_elevator_prompt(runtime_shell, "move");
    }
    let surface_id = runtime_shell
        .elevator_cursor
        .as_ref()
        .map(|cursor| cursor.surface_id.clone())
        .context("elevator prompt requires a cursor surface")?;
    move_visible_cursor_slot(
        &mut runtime_shell.elevator_cursor,
        surface_id,
        option_count,
        delta,
        &mut runtime_shell.last_audio_events,
    )
}

fn move_visible_gift_pokemon_cursor(
    runtime_shell: &mut BevyRuntimeShell,
    delta: isize,
) -> Result<()> {
    let snapshot = runtime_shell.shell.snapshot()?;
    let option_count = visible_gift_pokemon_prompt_options(&snapshot, runtime_shell).len();
    if option_count == 0 {
        runtime_shell.gift_pokemon_cursor = None;
        record_visible_runtime_action(runtime_shell, "ui:gift_pokemon:move:none_visible")?;
        runtime_shell
            .last_audio_events
            .push("no compiled gift Pokemon prompt is visible".to_string());
        set_shell_action_status(runtime_shell, "NO GIFT POKEMON");
        trim_event_log(&mut runtime_shell.last_audio_events);
        return Ok(());
    }
    let surface_id = runtime_shell
        .gift_pokemon_cursor
        .as_ref()
        .map(|cursor| cursor.surface_id.clone())
        .context("gift Pokemon prompt requires a cursor surface")?;
    move_visible_cursor_slot(
        &mut runtime_shell.gift_pokemon_cursor,
        surface_id,
        option_count,
        delta,
        &mut runtime_shell.last_audio_events,
    )
}

