fn apply_visible_name_rival_for_script_command(
    runtime_shell: &mut BevyRuntimeShell,
    source_script: &str,
    command_index: usize,
) -> Result<bool> {
    if compiled_special_routine_at(runtime_shell, source_script, command_index)?.as_deref()
        != Some("NameRival")
    {
        return Ok(false);
    }
    apply_visible_name_rival(runtime_shell, source_script, command_index)?;
    Ok(true)
}

fn apply_visible_name_rival(
    runtime_shell: &mut BevyRuntimeShell,
    source_script: &str,
    command_index: usize,
) -> Result<()> {
    let snapshot = runtime_shell.shell.snapshot()?;
    let rival_name = snapshot
        .script_events
        .variables
        .get("_rival_name")
        .cloned()
        .with_context(|| {
            format!(
                "script {source_script}:{command_index} NameRival requires exact _rival_name variable"
            )
        })?;
    if rival_name.trim().is_empty() {
        anyhow::bail!(
            "script {source_script}:{command_index} NameRival requires non-empty _rival_name"
        );
    }
    record_visible_runtime_action(
        runtime_shell,
        format!("script:special:name_rival:{source_script}:{command_index}:{rival_name}"),
    )?;
    let special = runtime_shell.shell.name_rival_special(rival_name)?;
    runtime_shell.last_audio_events.push(format!(
        "name rival source={} command={} outcome={:?} checksum={:?}",
        source_script, command_index, special.outcome.effect, special.state_checksum
    ));
    activate_visible_special_boundary_if_needed(runtime_shell, &special.outcome.effect)?;
    Ok(())
}

fn apply_visible_move_tutor(runtime_shell: &mut BevyRuntimeShell) -> Result<()> {
    let snapshot = runtime_shell.shell.snapshot()?;
    let party_index = selected_party_index(runtime_shell)?;
    let slot = snapshot
        .party
        .slots
        .iter()
        .find(|slot| slot.index == party_index)
        .with_context(|| format!("selected party index {party_index} is not in the party"))?;
    if slot.pokemon.moves.len() >= 4 {
        record_visible_runtime_action(
            runtime_shell,
            format!("special:move_tutor:{party_index}:move_list_full"),
        )?;
        runtime_shell.last_audio_events.push(format!(
            "selected party index {party_index} has no open move slot"
        ));
        set_shell_action_status(runtime_shell, "MOVE LIST FULL");
        trim_event_log(&mut runtime_shell.last_audio_events);
        return Ok(());
    }
    let known_moves = slot
        .pokemon
        .moves
        .iter()
        .map(|learned| learned.name.as_str())
        .collect::<std::collections::BTreeSet<_>>();
    let teachable_moves = snapshot
        .moves
        .iter()
        .filter(|candidate| !known_moves.contains(candidate.move_id.as_str()))
        .collect::<Vec<_>>();
    if teachable_moves.is_empty() {
        anyhow::bail!(
            "compiled move catalog has no teachable move for selected party index {party_index}"
        );
    }
    let slot_index = slot.index;
    let selected_index = runtime_shell.script_command_cursor % teachable_moves.len();
    let move_id = teachable_moves[selected_index].move_id.clone();
    record_visible_runtime_action(
        runtime_shell,
        format!("special:move_tutor:{slot_index}:{move_id}"),
    )?;
    let special = runtime_shell
        .shell
        .teach_party_move_special(slot_index, move_id.clone())?;
    runtime_shell.last_audio_events.push(format!(
        "move tutor {}/{} move={} party_index={} outcome={:?} checksum={:?}",
        selected_index + 1,
        teachable_moves.len(),
        move_id,
        slot_index,
        special.outcome.effect,
        special.state_checksum
    ));
    activate_visible_special_boundary_if_needed(runtime_shell, &special.outcome.effect)?;
    Ok(())
}

